265	// 共享交易只计一笔：多候选引用不重复计数；胜出确认后释放位置。
266	func TestCapacitySharedTxCountsOnce(t *testing.T) {
267		keys := genKeys(t, 4)
268		n, _ := newTestNodeCap(t, keys, 10, 2)
269	
270		shared := NewTransaction(keys[0].priv, 1, []byte("shared"), 1, 100)
271		other := NewTransaction(keys[1].priv, 1, []byte("other"), 1, 100)
272		n.Submit(shared)
273		n.Submit(other)
274		local, _ := n.Propose() // 本地提议含两笔
275		if len(local.TxIDs) != 2 {
276			t.Fatalf("local proposal = %v, want both txs", local.TxIDs)
277		}
278		// 竞争候选只含 shared：shared 被两个候选引用，仍只算一笔（池计数 2，已满）。
279		if _, err := n.RegisterCandidate(1, []string{shared.ID()}); err != nil {
280			t.Fatal(err)
281		}
282		c := NewTransaction(keys[2].priv, 1, []byte("c"), 1000, 100)
283		if _, err := n.Submit(c); reason(err) != ReasonPoolFull {
284			t.Fatalf("protected pool got %v, want %s", err, ReasonPoolFull)
