568		n.Submit(a)
569		b := NewTransaction(keys[1].priv, 1, []byte("b"), 2, 100)
570		res, err := n.Submit(b) // 挤出 a
571		if err != nil || res.EvictedID != a.ID() {
572			t.Fatalf("eviction: %+v %v", res, err)
573		}
574		if _, err := n.EndRound(); err != nil { // 轮次 2
575			t.Fatal(err)
576		}
577		if _, err := n.EndRound(); err != nil { // 轮次 3
578			t.Fatal(err)
579		}
580		info, _ := n.Tx(a.ID())
581		if info.Status != StatusDropped || info.DropReason != DropReasonPoolCapacity || info.DropRound != 1 {
582			t.Fatalf("dropped tx must not become expired: %+v", info)
